import streamlit as st
import pandas as pd

from utils.database import get_database_connection


def show_sql_insights():

    st.markdown(
        '<div class="section-title">SQL Insights</div>',
        unsafe_allow_html=True
    )

    st.write(
        "Select an analytical question. "
        "The answer is generated by executing the "
        "corresponding SQL query on the MySQL database."
    )

    # ========================================================
    # QUESTIONS
    # ========================================================

    questions = {

        # ----------------------------------------------------
        # 1. Average PM2.5 by City
        # ----------------------------------------------------

        "Which cities have the highest average PM2.5?":

        """
        SELECT
            city,
            ROUND(AVG(pm25), 2) AS avg_pm25
        FROM air_quality
        GROUP BY city
        ORDER BY avg_pm25 DESC;
        """,

        # ----------------------------------------------------
        # 2. Monthly Average PM2.5
        # ----------------------------------------------------

        "What is the monthly PM2.5 trend?":

        """
        SELECT
            YEAR(recorded_at) AS year,
            MONTH(recorded_at) AS month,
            ROUND(AVG(pm25), 2) AS avg_pm25
        FROM air_quality
        GROUP BY
            YEAR(recorded_at),
            MONTH(recorded_at)
        ORDER BY
            year,
            month;
        """,

        # ----------------------------------------------------
        # 3. Peak Pollution Hours
        # ----------------------------------------------------

        "What are the peak pollution hours?":

        """
        SELECT
            HOUR(recorded_at) AS hour,
            ROUND(AVG(pm25), 2) AS avg_pm25
        FROM air_quality
        GROUP BY HOUR(recorded_at)
        ORDER BY avg_pm25 DESC;
        """,

        # ----------------------------------------------------
        # 4. Rank Cities
        # ----------------------------------------------------

        "How do cities rank by average PM2.5?":

        """
        SELECT
            city,
            ROUND(AVG(pm25), 2) AS avg_pm25,
            RANK() OVER (
                ORDER BY AVG(pm25) DESC
            ) AS pollution_rank
        FROM air_quality
        GROUP BY city
        ORDER BY pollution_rank;
        """,

        # ----------------------------------------------------
        # 5. Top 10 Highest PM2.5 Observations
        # ----------------------------------------------------

        "What are the 10 highest PM2.5 observations?":

        """
        SELECT
            city,
            recorded_at,
            pm25
        FROM air_quality
        WHERE pm25 IS NOT NULL
        ORDER BY pm25 DESC
        LIMIT 10;
        """,

        # ----------------------------------------------------
        # 6. PM2.5 vs PM10
        # ----------------------------------------------------

        "How does PM2.5 compare with PM10 across cities?":

        """
        SELECT
            city,
            ROUND(AVG(pm25), 2) AS avg_pm25,
            ROUND(AVG(pm10), 2) AS avg_pm10
        FROM air_quality
        GROUP BY city
        ORDER BY avg_pm25 DESC;
        """,

        # ----------------------------------------------------
        # 7. Weekday vs Weekend
        # ----------------------------------------------------

        "How does PM2.5 differ between weekdays and weekends?":

        """
        SELECT
            CASE
                WHEN DAYOFWEEK(recorded_at)
                     IN (1, 7)
                THEN 'Weekend'
                ELSE 'Weekday'
            END AS day_type,

            ROUND(AVG(pm25), 2) AS avg_pm25

        FROM air_quality

        GROUP BY
            CASE
                WHEN DAYOFWEEK(recorded_at)
                     IN (1, 7)
                THEN 'Weekend'
                ELSE 'Weekday'
            END;
        """
    }

    # ========================================================
    # QUESTION SELECTOR
    # ========================================================

    selected_question = st.selectbox(
        "Select a question",
        list(questions.keys())
    )

    # ========================================================
    # RUN QUERY
    # ========================================================

    if st.button(
        "▶ Run SQL Query",
        type="primary"
    ):

        query = questions[selected_question]

        try:

            # Get MySQL connection
            engine = get_database_connection()

            # Execute actual SQL query
            result = pd.read_sql(
                query,
                engine
            )

            st.success(
                "SQL query executed successfully."
            )

            # =================================================
            # RESULT TABLE
            # =================================================

            st.markdown(
                "### Query Result"
            )

            st.dataframe(
                result,
                use_container_width=True,
                hide_index=True
            )

            # =================================================
            # VISUALIZATIONS
            # =================================================

            # -------------------------------------------------
            # 1. City-wise Average PM2.5
            # -------------------------------------------------

            if selected_question == \
                    "Which cities have the highest average PM2.5?":

                chart_data = result.head(10)

                st.markdown(
                    "### Top 10 Cities by Average PM2.5"
                )

                st.bar_chart(
                    chart_data.set_index(
                        "city"
                    )["avg_pm25"]
                )

            # -------------------------------------------------
            # 2. Monthly PM2.5 Trend
            # -------------------------------------------------

            elif selected_question == \
                    "What is the monthly PM2.5 trend?":

                chart_data = result.copy()

                # Create proper date from year and month
                chart_data["date"] = pd.to_datetime(
                    chart_data["year"].astype(str)
                    + "-"
                    + chart_data["month"].astype(str)
                    + "-01"
                )

                chart_data = chart_data.set_index(
                    "date"
                )

                st.markdown(
                    "### Monthly PM2.5 Trend"
                )

                st.line_chart(
                    chart_data["avg_pm25"]
                )

            # -------------------------------------------------
            # 3. Peak Pollution Hours
            # -------------------------------------------------

            elif selected_question == \
                    "What are the peak pollution hours?":

                chart_data = result.sort_values(
                    "hour"
                )

                chart_data = chart_data.set_index(
                    "hour"
                )

                st.markdown(
                    "### PM2.5 by Hour"
                )

                st.line_chart(
                    chart_data["avg_pm25"]
                )

            # -------------------------------------------------
            # 4. PM2.5 vs PM10
            # -------------------------------------------------

            elif selected_question == \
                    "How does PM2.5 compare with PM10 across cities?":

                chart_data = result.head(10)

                chart_data = chart_data.set_index(
                    "city"
                )

                st.markdown(
                    "### PM2.5 vs PM10"
                )

                st.bar_chart(
                    chart_data[
                        ["avg_pm25", "avg_pm10"]
                    ]
                )

        except Exception as e:

            st.error(
                f"Database query failed: {e}"
            )